// 或已撤回，返回 ErrAccessDenied，结果中不含任何受保护内容。
func (s *Store) Read(actor Actor, patientID, encounterID ID, category string) (ReadResult, error) {
	if !actor.valid() || actor.Kind != "receiver" {
		return ReadResult{}, ErrAccessDenied
	}
