func TestCorrectionVersionChainAndConflict(t *testing.T) {
	s, clk := newTestStore(t)
	pid, eid := setupPatientEncounter(t, s)
	r, _ := s.CreateDraft(doc, pid, eid, Diagnosis, "旧诊断")
	v1, err := s.ActivateRecord(doc, r.ID)
	if err != nil {
		t.Fatal(err)
	}

	// 缺原因、非法版本号。
